#pragma once

#include <filesystem>

namespace r2fix {
class Startup;

// Rayman2Fix.ini is the only user-maintained configuration.
// ubi.ini is a game-facing compatibility file regenerated by the launcher.
// Preserve unrelated CD/game settings (e.g. Language) and never overwrite
// arbitrary unknown sections. Fail on unsupported user resolutions.
void synchronize_rayman2_ubi_ini(const std::filesystem::path& game_dir,
                                Startup& startup);

} // namespace r2fix
